		case IE_NOMEMBER:
			mes "^ff0000To enter, you must create or join a party of 1 or more members.^000000";
			close;
		case IE_NOINSTANCE:
			mes "^ff0000The party leader has not used the device.^000000";
			close;
		case IE_OTHER:
			mes "An unknown error has occurred.";// Custom
			close;
		}
	case 3:
